begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('da100000-0000-0000-0000-000000000001','TRIP-A','Logística ficticia A'),('da100000-0000-0000-0000-000000000002','TRIP-B','Logística ficticia B');
insert into auth.users(id,email) values('da200000-0000-0000-0000-000000000001','trip-one@example.invalid'),('da200000-0000-0000-0000-000000000002','trip-two@example.invalid'),('da200000-0000-0000-0000-000000000003','trip-review@example.invalid'),('da200000-0000-0000-0000-000000000004','trip-finance@example.invalid');
insert into profiles(id,full_name,branch_id,active) select v.id,v.name,'da100000-0000-0000-0000-000000000001',true from(values('da200000-0000-0000-0000-000000000001'::uuid,'Colaborador ficticio 1'),('da200000-0000-0000-0000-000000000002'::uuid,'Colaborador ficticio 2'),('da200000-0000-0000-0000-000000000003'::uuid,'Supervisor ficticio'),('da200000-0000-0000-0000-000000000004'::uuid,'Finanzas ficticias'))v(id,name);
insert into user_roles(user_id,role_id,branch_id) select v.id,r.id,'da100000-0000-0000-0000-000000000001' from(values('da200000-0000-0000-0000-000000000001'::uuid,'LOGISTICA'),('da200000-0000-0000-0000-000000000002'::uuid,'LOGISTICA'),('da200000-0000-0000-0000-000000000003'::uuid,'GERENCIA_OPERATIVA'),('da200000-0000-0000-0000-000000000004'::uuid,'FINANZAS'))v(id,code)join roles r on r.code=v.code;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
create function pg_temp.claim(dep text,arr text,key uuid default gen_random_uuid()) returns jsonb language sql as $$select jsonb_build_object('branch_id','da100000-0000-0000-0000-000000000001','origin','HemoCura ficticio','destination','Centro ficticio','purpose','ENTREGA','departure_local',dep,'arrival_local',arr,'request_id',key)$$;
set local role authenticated;select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000001',true);
select pg_temp.ok(has_permission('TRIPS_WRITE') and not has_permission('ACCESS_ADMIN') and not has_permission('TRIPS_REVIEW'),'logistics role can submit but cannot administer or approve');
select pg_temp.ok((select count(*)=1 from vw_logistics_trip_branches),'worker branch selector excludes unauthorized branches');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T09:00','2026-10-12T17:00'))$q$,'weekday trip within working hours is rejected');
select pg_temp.ok(logistics_trip_schedule('2026-10-12 18:00-04')->>'classification'='DENTRO_DE_JORNADA','exact weekday end is within authorized shift');
select pg_temp.ok(logistics_trip_schedule('2026-10-10 12:00-04')->>'classification'='DENTRO_DE_JORNADA' and logistics_trip_schedule('2026-10-10 12:01-04')->>'classification'='DESPUES_DE_JORNADA','Saturday noon boundary is correct');
select pg_temp.ok(logistics_trip_schedule('2026-10-11 10:00-04')->>'classification'='DIA_NO_LABORABLE','Sunday has no regular working shift');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2099-10-12T17:00','2099-10-12T19:00'))$q$,'unfinished future trip is rejected');
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','da300000-0000-0000-0000-000000000001'));
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','da300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select count(*)=1 and bool_and(amount is null and status='ENVIADO' and worker_id=auth.uid() and worker_name='Colaborador ficticio 1') from logistics_trips),'retry is idempotent and stamps real worker without promising incentive');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T18:00','2026-10-12T20:00'))$q$,'overlapping duplicate claim is rejected');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','da300000-0000-0000-0000-000000000001')||'{"origin":"Changed"}')$q$,'same request key cannot be reused with changed payload');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-13T17:00','2026-10-13T19:00')||'{"branch_id":"da100000-0000-0000-0000-000000000002"}')$q$,'worker cannot claim another branch');
select pg_temp.denied($q$update logistics_trips set status='APROBADO',amount=500,review_note='Autorizado'$q$,'direct self approval is rejected');
select pg_temp.denied($q$update logistics_trips set worker_id='da200000-0000-0000-0000-000000000002'$q$,'worker identity cannot be changed');
select pg_temp.denied($q$delete from logistics_trip_history$q$,'worker cannot delete incentive audit');
select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000002',true);
select pg_temp.ok((select count(*)=0 from logistics_trips) and (select count(*)=0 from logistics_trip_history),'workers cannot read other worker claims or history');
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-10T11:00','2026-10-10T13:00'));
select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000003',true);
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-14T18:30','2026-10-14T20:00'));
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','Autorrevisión') from logistics_trips where worker_id=auth.uid()))$q$,'supervisor cannot approve their own trip even with review permission');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',0,'review_note','Prueba') from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'))$q$,'incentive must be positive and authorized');
select pg_temp.denied($q$update logistics_trips set schedule_snapshot='{}',status='APROBADO',amount=500,review_note='Prueba' where request_id='da300000-0000-0000-0000-000000000001'$q$,'reviewer cannot replace preserved working schedule');
select logistics_trip_action('RETURN',(select jsonb_build_object('id',id,'revision',revision,'review_note','Añadir referencia de entrega') from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'));
select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000001',true);
select logistics_trip_action('RESUBMIT',(select pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00')||jsonb_build_object('id',id,'revision',revision,'delivery_reference','ENTREGA-FICTICIA') from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select status='ENVIADO' and revision=3 and reviewed_by is null from logistics_trips),'correction resubmits with fresh review and audit revision');
select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000003',true);
select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','Entrega verificada y tarifa autorizada','scheduled_end_local','2026-10-12T01:00') from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select amount=500 and reviewed_by=auth.uid() and scheduled_end_at='2026-10-12 18:00-04'::timestamptz from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'),'review stamps actual supervisor and authorized schedule rather than supplied fake hours');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',1,'amount',900,'review_note','Prueba') from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'))$q$,'stale review cannot overwrite approved incentive');
select pg_temp.denied($q$update logistics_trips set origin='Falso',status='DEVUELTO',review_note='Prueba' where request_id='da300000-0000-0000-0000-000000000001'$q$,'supervisor cannot alter reported trip facts');
select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000004',true);
select pg_temp.denied($q$select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','da100000-0000-0000-0000-000000000001','payroll_reference','BATCH-INVALIDO','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips)))$q$,'mixed pending and approved settlement batch is rejected atomically');
select pg_temp.ok((select count(*)=0 from logistics_trips where status='LIQUIDADO'),'invalid settlement batch leaves all awards unchanged');
select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','da100000-0000-0000-0000-000000000001','payroll_reference','NOMINA-FICTICIA','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips where status='APROBADO')));
select pg_temp.ok((select status='LIQUIDADO' and amount=500 and settled_by=auth.uid() and payroll_reference='NOMINA-FICTICIA' from logistics_trips where request_id='da300000-0000-0000-0000-000000000001'),'finance records approved amount and payroll reference without modifying the award');
select pg_temp.denied($q$update logistics_trips set amount=900 where status='LIQUIDADO'$q$,'settled incentive is immutable');
select pg_temp.denied($q$select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','da100000-0000-0000-0000-000000000001','payroll_reference','DUP','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips where status='LIQUIDADO')))$q$,'same award cannot be settled twice');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','No autorizado') from logistics_trips where status='ENVIADO' limit 1))$q$,'finance cannot independently approve unreviewed trips');
reset role;
update profiles set active=false where id='da200000-0000-0000-0000-000000000001';set local role authenticated;select set_config('request.jwt.claim.sub','da200000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-13T17:00','2026-10-13T19:00'))$q$,'inactive worker cannot submit');
reset role;set local role anon;
select pg_temp.denied($q$select logistics_trip_action('CREATE','{}')$q$,'anonymous cannot submit incentive claims');
rollback;
